std::vector<int> src = {5, 6};
std::vector<int> v = {1, 2}; // Must support push_back
std::list<int> l = {1, 2};   // Must support push_front/insert

// 1. Append (Uses push_back)
std::copy(src.begin(), src.end(), std::back_inserter(v));

// 2. Prepend (Uses push_front)
std::copy(src.begin(), src.end(), std::front_inserter(l));

// 3. Specific Position (Uses insert(pos, val))
auto pos = std::next(l.begin());
std::copy(src.begin(), src.end(), std::inserter(l, pos));
